import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const images = Array.from({ length: 8 }, (_, i) => `/images/a${i + 1}.gif`);



function Home() {
  const [selectedImages, setSelectedImages] = useState([]);
  const navigate = useNavigate();

  const toggleImage = (img) => {
    setSelectedImages((prev) =>
      prev.includes(img) ? prev.filter((i) => i !== img) : [...prev, img]
    );
  };

  const handleGenerate = () => {
    localStorage.setItem("selectedImages", JSON.stringify(selectedImages));
    navigate("/generate");
  };

  return (
    <div>
      <h1>Select Images</h1>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: "10px",
          padding: "20px",
        }}
      >
        {images.map((img, i) => {
          const selectedIndex = selectedImages.indexOf(img);
          return (
            <div key={i} style={{ position: "relative" }}>
              <img
                src={img}
                alt={`tile-${i}`}
                onClick={() => toggleImage(img)}
                style={{
                  width: "100%",
                  cursor: "pointer",
                  border: selectedIndex !== -1 ? "3px solid yellow" : "1px solid gray",
                  borderRadius: "8px",
                }}
              />
              {selectedIndex !== -1 && (
                <div
                  style={{
                    position: "absolute",
                    top: "8px",
                    left: "8px",
                    background: "rgba(0,0,0,0.7)",
                    color: "white",
                    borderRadius: "50%",
                    width: "24px",
                    height: "24px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: "14px",
                  }}
                >
                  {selectedIndex + 1}
                </div>
              )}
            </div>
          );
        })}
      </div>
      <button
        onClick={handleGenerate}
        disabled={selectedImages.length < 2}
        style={{ margin: "20px", padding: "10px 20px", fontSize: "16px" }}
      >
        Generate
      </button>
    </div>
  );
}

export default Home;
